#!/usr/bin/env bash
# --- OTK stage timing markers (nanoseconds) ---
__otk_ts()   { date +%s%N; }                      # ns since epoch
__otk_mark() { echo "__OTK_TS__ $1 $(__otk_ts)"; }
set -eo pipefail

echo "== run_zk_demo: start =="
__otk_mark start
__otk_mark ensure_submodules
PHASE3_DIR="$(cd "$(dirname "$0")/.." && pwd)"
CIRCUITS_DIR="$PHASE3_DIR/circuits"
BUILD_DIR="$PHASE3_DIR/build"
PTAU_DIR="$PHASE3_DIR/ptau"

mkdir -p "$BUILD_DIR" "$PTAU_DIR"

