export PATH=""$(printf "%s" "${PATH:-}" | tr ":" "\n" | grep -v "^/mnt/c/" | paste -sd ":" - 2>/dev/null || true)":${PATH}"
hash -r || true

# ---- OTK toggle: usar Node do sistema (NodeSource /usr/bin) ao inves do NVM ----
# Use assim: OTK_USE_SYSTEM_NODE=1 bash phase3-zk/scripts/run_zk_demo.sh
if [ "${OTK_USE_SYSTEM_NODE:-0}" = "1" ]; then
  export PATH="/usr/local/bin:/usr/bin:$HOME/.cargo/bin:/usr/sbin:/sbin:/bin"
  hash -r || true
else
# NVM disabled: using system node (/usr/bin/node)
# (NVM was causing failures under nounset/WSL)
  export PATH="$HOME/.cargo/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
  hash -r || true
fi

# Print toolchain
echo "node=$(command -v node || true)"; node -v || true
echo "npm=$(command -v npm || true)"; npm -v || true
echo "snarkjs=$(command -v snarkjs || true)"; snarkjs -h 2>/dev/null | head -n 1 || true
echo "circom=$(command -v circom || true)"; circom --version || true

# 0) garantir submodules (circomlib)
bash "$PHASE3_DIR/scripts/ensure_submodules.sh"

# 1) preparar circuit deps (submodule)
if [ ! -d "$CIRCUITS_DIR/circomlib" ]; then
  echo "ERROR: circomlib not found at: $CIRCUITS_DIR/circomlib"
  echo "DEBUG: PWD=$(pwd)"
  echo "DEBUG: ls -la circuits_dir:"
  ls -la "$CIRCUITS_DIR" || true
  echo "DEBUG: git submodule status:"
  (cd "$PHASE3_DIR/.." && git submodule status --recursive) || true
  exit 1
fi

# 2) compilar circuito
CIRCUIT="$CIRCUITS_DIR/preimage2.circom"
if [ ! -f "$CIRCUIT" ]; then
  echo "ERROR: circuit file not found: $CIRCUIT"
  exit 1
fi

echo "== circom compile =="
__otk_mark circom_compile
circom "$CIRCUIT" --r1cs --wasm --sym -o "$BUILD_DIR"

# 3) input.json (se nao existir, cria exemplo)
if [ ! -f "$BUILD_DIR/input.json" ]; then
  cat > "$BUILD_DIR/input.json" <<'JSON'
{"a":"3","b":"11"}
JSON
fi

# 4) witness
echo "== witness =="
__otk_mark witness
node "$BUILD_DIR/preimage2_js/generate_witness.js" "$BUILD_DIR/preimage2_js/preimage2.wasm" "$BUILD_DIR/input.json" "$BUILD_DIR/witness.wtns"

# 5) PTAU (pequeno demo: pot12)
echo "== ptau =="
__otk_mark ptau
if [ ! -f "$PTAU_DIR/pot12_phase2.ptau" ]; then
  snarkjs powersoftau new bn128 12 "$PTAU_DIR/pot12_0000.ptau" -v
  snarkjs powersoftau contribute "$PTAU_DIR/pot12_0000.ptau" "$PTAU_DIR/pot12_0001.ptau" --name="first" -v -e="otk"
  snarkjs powersoftau prepare phase2 "$PTAU_DIR/pot12_0001.ptau" "$PTAU_DIR/pot12_phase2.ptau" -v
fi

# 6) Groth16 setup + proof
echo "== groth16 =="
__otk_mark groth16
snarkjs groth16 setup "$BUILD_DIR/preimage2.r1cs" "$PTAU_DIR/pot12_phase2.ptau" "$BUILD_DIR/preimage2_0000.zkey"
snarkjs zkey contribute "$BUILD_DIR/preimage2_0000.zkey" "$BUILD_DIR/preimage2_final.zkey" --name="final" -v -e="otk"
snarkjs zkey export verificationkey "$BUILD_DIR/preimage2_final.zkey" "$BUILD_DIR/verification_key.json"

snarkjs groth16 prove "$BUILD_DIR/preimage2_final.zkey" "$BUILD_DIR/witness.wtns" "$BUILD_DIR/proof.json" "$BUILD_DIR/public.json"
snarkjs groth16 verify "$BUILD_DIR/verification_key.json" "$BUILD_DIR/public.json" "$BUILD_DIR/proof.json"

__otk_mark end
echo "== run_zk_demo: OK =="

